// ==UserScript==
// @name         奶包
// @namespace    local.naibao
// @version      1.0
// @description  那一夜，奶龙和豆包喝醉了...
// @match        https://www.doubao.com/*
// @match        https://doubao.com/*
// @run-at       document-start
// @grant        none
// ==/UserScript==

(function () {
  'use strict';

  /* ==================== 配置模块 ==================== */

  // 品牌词替换
  const OLD_WORD = '豆包';
  const NEW_WORD = '奶包';

  // 欢迎语候选池：页面每次加载随机取一句
  const GREETINGS = [
    '你好呀，我是奶包',
    '哈哈哈哈哈哈',
    '我才是奶包，我才是奶包',
    '今夜星光闪闪，爱你的心满满',
    '那天豆包与奶龙喝醉了...',
    '对不起上次我错了，让我们再错一次',
    '啊我上次说错了，真是对不起',
    '让我用最直白、最一针见血的话与你开始',
    '豆馅补充中',
    '哎呀被你看出来了',
    '你也没说选正确答案啊',
    '接下来绝不会犯之前的错误',
    '正在创作参考文献',
    '正在走路去洗车店...'
  ];
  const GREETING_SOURCE = '有什么我能帮你的吗';
  const GREETING_PATTERN = /有什么我能帮你的吗[？?]?/g;
  const GREETING = GREETINGS[Math.floor(Math.random() * GREETINGS.length)];

  // 图片素材以 base64 内联，脚本单文件自包含
  const FAVICON_DATA_URL = 'data:image/png;base64,';
  const BODY_DATA_URLS = [
    'data:image/webp;base64,',
    'data:image/webp;base64,',
    'data:image/webp;base64,'
  ];
  const BODY_DATA_URL = BODY_DATA_URLS[Math.floor(Math.random() * BODY_DATA_URLS.length)];

  const DECO_ID = 'naibao-deco';
  const DECO_STYLE_ID = 'naibao-deco-style';
  const HINT_ID = 'naibao-hint';

  /* ==================== 文本改写模块 ==================== */

  /**
   * 改写任意字符串，按顺序处理：
   * 一、已是欢迎语的文本原样保留；
   * 二、欢迎语先以占位符隔离，品牌词替换完成后再回填，保证随机欢迎语措辞与原文一致；
   * 三、其余文本中的品牌词整体替换。
   */
  const GREETING_SLOT = '\u0000naibao-slot\u0000';

  function rewriteText(value) {
    if (!value) return value;

    if (GREETINGS.indexOf(value.trim()) !== -1) return value;

    let next = value;
    let greeted = false;

    if (next.indexOf(GREETING_SOURCE) !== -1) {
      next = next.replace(GREETING_PATTERN, GREETING_SLOT);
      greeted = true;
    }
    if (next.indexOf(OLD_WORD) !== -1) {
      next = next.split(OLD_WORD).join(NEW_WORD);
    }
    if (greeted) {
      next = next.split(GREETING_SLOT).join(GREETING);
    }
    return next;
  }

  const SKIP_TAGS = { SCRIPT: true, STYLE: true, NOSCRIPT: true, TEXTAREA: true };
  const ATTR_NAMES = ['placeholder', 'title', 'aria-label', 'alt', 'data-placeholder'];
  const ATTR_SELECTOR = ATTR_NAMES.map((name) => '[' + name + ']').join(',');

  /** 文本改写范围：脚本样式、输入编辑区内部文字、脚本自身注入的节点保持原样 */
  function skipTextRegion(el) {
    if (!el || el.nodeType !== 1) return false;
    if (SKIP_TAGS[el.tagName]) return true;
    if (el.hasAttribute('data-naibao')) return true;
    if (el.isContentEditable) return true;
    return false;
  }

  /** 属性改写范围：输入框的占位符属于展示文案，仍需改写 */
  function skipAttrRegion(el) {
    if (!el || el.nodeType !== 1) return false;
    return el.hasAttribute('data-naibao');
  }

  function processTextNode(node) {
    const value = node.nodeValue;
    const next = rewriteText(value);
    if (next !== value) node.nodeValue = next;
  }

  function processAttributes(el) {
    for (let i = 0; i < ATTR_NAMES.length; i += 1) {
      const name = ATTR_NAMES[i];
      if (!el.hasAttribute(name)) continue;
      const value = el.getAttribute(name);
      const next = rewriteText(value);
      if (next !== value) el.setAttribute(name, next);
    }
  }

  /** 遍历指定子树，完成文本节点与属性的一次性改写 */
  function walk(root) {
    if (!root) return;

    if (root.nodeType === 3) {
      const parent = root.parentElement;
      if (parent && !skipTextRegion(parent)) processTextNode(root);
      return;
    }
    if (root.nodeType !== 1) return;
    if (skipTextRegion(root) && skipAttrRegion(root)) return;

    if (!skipAttrRegion(root)) processAttributes(root);

    const holders = root.querySelectorAll(ATTR_SELECTOR);
    for (let i = 0; i < holders.length; i += 1) {
      if (!skipAttrRegion(holders[i])) processAttributes(holders[i]);
    }

    if (skipTextRegion(root)) return;

    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        const parent = node.parentElement;
        if (parent && skipTextRegion(parent)) return NodeFilter.FILTER_REJECT;
        const value = node.nodeValue;
        if (value && (value.indexOf(OLD_WORD) !== -1 || value.indexOf(GREETING_SOURCE) !== -1)) {
          return NodeFilter.FILTER_ACCEPT;
        }
        return NodeFilter.FILTER_REJECT;
      }
    });

    let node = walker.nextNode();
    while (node) {
      processTextNode(node);
      node = walker.nextNode();
    }
  }

  /** 监听页面动态渲染与标题、占位符变化 */
  function startTextObserver() {
    const observer = new MutationObserver((records) => {
      for (let i = 0; i < records.length; i += 1) {
        const record = records[i];
        if (record.type === 'childList') {
          for (let j = 0; j < record.addedNodes.length; j += 1) walk(record.addedNodes[j]);
        } else if (record.type === 'characterData') {
          const parent = record.target.parentElement;
          if (parent && !skipTextRegion(parent)) processTextNode(record.target);
        } else if (record.type === 'attributes') {
          if (!skipAttrRegion(record.target)) processAttributes(record.target);
        }
      }
      // 丢弃本次改写自身产生的变更记录，避免重复处理
      observer.takeRecords();
    });

    observer.observe(document.documentElement, {
      childList: true,
      subtree: true,
      characterData: true,
      attributes: true,
      attributeFilter: ATTR_NAMES
    });
  }

  /* ==================== 标签页图标模块 ==================== */

  function applyFavicon() {
    const head = document.head || document.documentElement;
    if (!head) return;

    const links = document.querySelectorAll('link[rel~="icon"], link[rel="apple-touch-icon"], link[rel="mask-icon"]');

    if (!links.length) {
      const link = document.createElement('link');
      link.rel = 'icon';
      link.type = 'image/png';
      link.href = FAVICON_DATA_URL;
      link.setAttribute('data-naibao', '1');
      head.appendChild(link);
      return;
    }

    for (let i = 0; i < links.length; i += 1) {
      const link = links[i];
      if (link.getAttribute('href') === FAVICON_DATA_URL) continue;
      link.setAttribute('type', 'image/png');
      link.setAttribute('href', FAVICON_DATA_URL);
    }
  }

  /* ==================== 全身照装饰模块 ==================== */

  function injectDecoStyle() {
    if (document.getElementById(DECO_STYLE_ID)) return;
    const style = document.createElement('style');
    style.id = DECO_STYLE_ID;
    style.textContent = [
      '#' + DECO_ID + ' {',
      '  position: fixed;',
      '  left: 0;',
      '  bottom: 0;',
      '  width: 220px;',
      '  height: auto;',
      '  max-width: none;',
      '  margin: 0;',
      '  padding: 0;',
      '  pointer-events: auto;',
      '  cursor: pointer;',
      '  user-select: none;',
      '  -webkit-user-drag: none;',
      '  z-index: 2147483000;',
      '  opacity: 0;',
      '  filter: drop-shadow(0 10px 26px rgba(0, 0, 0, 0.38));',
      '  animation: naibao-float 5s ease-in-out infinite;',
      '  transition: opacity 0.35s ease, width 0.2s ease;',
      '}',
      '@keyframes naibao-float {',
      '  0%, 100% { transform: translateY(0); }',
      '  50% { transform: translateY(-10px); }',
      '}',
      '#' + HINT_ID + ' {',
      '  position: fixed;',
      '  transform: translateX(-50%);',
      '  max-width: 260px;',
      '  padding: 7px 14px;',
      '  border-radius: 10px;',
      '  background: rgba(28, 28, 34, 0.94);',
      '  border: 1px solid rgba(255, 255, 255, 0.16);',
      '  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.4);',
      '  color: #f4f4f6;',
      '  font: 13px/1.5 "Microsoft YaHei", "PingFang SC", system-ui, sans-serif;',
      '  letter-spacing: 0.2px;',
      '  white-space: nowrap;',
      '  opacity: 0;',
      '  pointer-events: none;',
      '  z-index: 2147483001;',
      '  transition: opacity 0.2s ease;',
      '}'
    ].join('\n');
    (document.head || document.documentElement).appendChild(style);
  }

  function ensureDecoElement() {
    let img = document.getElementById(DECO_ID);
    if (!img) {
      img = document.createElement('img');
      img.id = DECO_ID;
      img.alt = '';
      img.draggable = false;
      img.src = BODY_DATA_URL;
      img.setAttribute('data-naibao', '1');
      img.addEventListener('load', () => {
        readAspect(img);
        decoSignature = '';
        layoutDeco();
      });
    }
    if (!img.isConnected && document.body) document.body.appendChild(img);
    return img;
  }

  function isVisible(el) {
    const rect = el.getBoundingClientRect();
    if (rect.width < 80 || rect.height < 14) return false;
    if (rect.bottom < 40 || rect.top > window.innerHeight - 10) return false;
    const style = getComputedStyle(el);
    if (style.display === 'none' || style.visibility === 'hidden') return false;
    if (Number(style.opacity) < 0.1) return false;
    if (el.getAttribute('aria-hidden') === 'true') return false;
    return true;
  }

  /** 定位当前页面真正在用的输入框 */
  function pickInput() {
    const candidates = document.querySelectorAll(
      'textarea, [contenteditable="true"], [contenteditable=""], [role="textbox"]'
    );
    let best = null;
    let bestScore = -Infinity;

    for (let i = 0; i < candidates.length; i += 1) {
      const el = candidates[i];
      if (!isVisible(el)) continue;
      const rect = el.getBoundingClientRect();
      const score = rect.bottom * 3 + rect.width * 0.2;
      if (score > bestScore) {
        bestScore = score;
        best = el;
      }
    }
    return best;
  }

  /** 由输入框向上收敛到输入卡片，遇到接近整屏宽的容器即停止 */
  function findInputCard(input) {
    let card = input;
    let current = input;
    for (let depth = 0; depth < 8 && current.parentElement; depth += 1) {
      const parent = current.parentElement;
      const rect = parent.getBoundingClientRect();
      if (rect.width > window.innerWidth * 0.92) break;
      if (rect.height > window.innerHeight * 0.6) break;
      card = parent;
      current = parent;
    }
    return card;
  }

  const BODY_ASPECT_FALLBACK = 459 / 660;
  const DECO_GAP = 12;
  const DECO_MIN_WIDTH = 110;

  // 双击隐藏仅对本次会话生效，刷新页面后重新出现
  let decoHidden = false;
  let decoAspect = BODY_ASPECT_FALLBACK;
  let decoSignature = '';
  let hintEl = null;
  let hintTimer = null;
  let clickTimer = null;

  /** 以真实图片比例为准，避免不同素材被拉伸 */
  function readAspect(img) {
    if (img.naturalWidth > 0 && img.naturalHeight > 0) {
      decoAspect = img.naturalWidth / img.naturalHeight;
    }
    return decoAspect;
  }

  /**
   * 三级定位策略，保证任何窗口尺寸都有落脚点：
   * 一、输入卡片右侧留白；
   * 二、输入卡片上方，右缘与卡片对齐；
   * 三、极小窗口下贴视口右下角，允许与卡片边缘交叠。
   */
  function resolvePlacement(card, viewportWidth, viewportHeight, idealWidth, idealHeight) {
    const rightSpace = viewportWidth - card.right - DECO_GAP - 4;
    if (rightSpace >= DECO_MIN_WIDTH) {
      return {
        left: card.right + DECO_GAP,
        bottom: viewportHeight - card.bottom - 2,
        width: Math.min(idealWidth, rightSpace)
      };
    }

    const upperSpace = card.top - DECO_GAP - 4;
    if (upperSpace >= 120) {
      const height = Math.min(idealHeight, upperSpace);
      const width = Math.min(idealWidth, height * decoAspect, viewportWidth - 24);
      const alignedLeft = Math.min(card.right - width, viewportWidth - width - 8);
      return {
        left: Math.max(8, alignedLeft),
        bottom: viewportHeight - card.top + DECO_GAP,
        width
      };
    }

    const compactWidth = Math.max(DECO_MIN_WIDTH, Math.min(idealWidth, viewportWidth * 0.5, 200));
    return {
      left: Math.max(6, viewportWidth - compactWidth - 6),
      bottom: 6,
      width: compactWidth
    };
  }

  function layoutDeco() {
    const img = ensureDecoElement();
    if (!img) return;

    if (decoHidden) {
      if (decoSignature !== 'hidden') {
        decoSignature = 'hidden';
        img.style.opacity = '0';
      }
      return;
    }

    const input = pickInput();
    if (!input) {
      if (decoSignature !== 'waiting') {
        decoSignature = 'waiting';
        img.style.opacity = '0';
        img.style.pointerEvents = 'none';
      }
      return;
    }

    readAspect(img);

    const card = findInputCard(input).getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;

    const idealHeight = Math.min(Math.max(card.height * 3, 320), 520, viewportHeight * 0.62);
    const idealWidth = idealHeight * decoAspect;

    const place = resolvePlacement(card, viewportWidth, viewportHeight, idealWidth, idealHeight);
    const signature = [Math.round(place.left), Math.round(place.width), Math.round(place.bottom)].join('|');
    if (signature === decoSignature) return;
    decoSignature = signature;

    img.style.width = Math.round(place.width) + 'px';
    img.style.left = Math.round(place.left) + 'px';
    img.style.bottom = Math.round(place.bottom) + 'px';
    img.style.opacity = '1';
    img.style.pointerEvents = 'auto';
    if (hintEl && hintEl.style.opacity === '1') placeHint(img);
  }

  /* ---------- 点击提示与双击隐藏 ---------- */

  function placeHint(img) {
    const rect = img.getBoundingClientRect();
    const centerX = rect.left + rect.width / 2;
    hintEl.style.left = Math.round(Math.min(Math.max(centerX, 96), window.innerWidth - 96)) + 'px';
    hintEl.style.top = Math.round(Math.max(8, rect.top - 42)) + 'px';
  }

  function showHint(img) {
    if (decoHidden) return;

    if (!hintEl) {
      hintEl = document.createElement('div');
      hintEl.id = HINT_ID;
      hintEl.textContent = '双击我可以暂时藏起来';
      hintEl.setAttribute('data-naibao', '1');
    }
    if (!hintEl.isConnected && document.body) document.body.appendChild(hintEl);

    placeHint(img);
    hintEl.style.opacity = '1';

    clearTimeout(hintTimer);
    hintTimer = setTimeout(() => {
      if (hintEl) hintEl.style.opacity = '0';
    }, 2600);
  }

  function hideDeco() {
    decoHidden = true;
    clearTimeout(hintTimer);
    if (hintEl) hintEl.style.opacity = '0';

    const img = document.getElementById(DECO_ID);
    if (img) {
      img.style.opacity = '0';
      img.style.pointerEvents = 'none';
    }
  }

  /** 单击给出提示，双击在提示出现前即完成隐藏 */
  function bindDecoEvents(img) {
    if (img.getAttribute('data-naibao-clickable')) return;
    img.setAttribute('data-naibao-clickable', '1');

    img.addEventListener('click', () => {
      if (clickTimer) {
        clearTimeout(clickTimer);
        clickTimer = null;
        return;
      }
      clickTimer = setTimeout(() => {
        clickTimer = null;
        showHint(img);
      }, 250);
    });

    img.addEventListener('dblclick', () => {
      if (clickTimer) {
        clearTimeout(clickTimer);
        clickTimer = null;
      }
      hideDeco();
    });
  }

  function mountDeco() {
    injectDecoStyle();
    const img = ensureDecoElement();
    bindDecoEvents(img);
    layoutDeco();

    let ticking = false;
    const schedule = () => {
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(() => {
        ticking = false;
        layoutDeco();
      });
    };

    window.addEventListener('resize', schedule, true);
    window.addEventListener('scroll', schedule, true);
    setInterval(layoutDeco, 400);
  }

  /* ==================== 启动流程 ==================== */

  function boot() {
    walk(document.documentElement);
    startTextObserver();
    applyFavicon();
    setInterval(applyFavicon, 1500);
    mountDeco();
  }

  applyFavicon();

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot, { once: true });
  } else {
    boot();
  }
})();
